package ru.domovoy.integrations.tuya

import org.junit.jupiter.api.Test
import java.io.ByteArrayInputStream
import java.io.EOFException
import java.io.IOException
import kotlin.test.assertContentEquals
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith

/** Golden packets were generated by TinyTuya 1.20.0 using only the fake key/nonces below. */
class TuyaLanProtocolTest {
    private val key = "0123456789abcdef".toByteArray()
    private val clientNonce = "abcdefghijklmnop".toByteArray()
    private val protocol = TuyaLanProtocol(key)

    @Test
    fun `session negotiation starts with the protocol compatible encrypted nonce`() {
        assertContentEquals(hex(START), protocol.encode(7, 3, clientNonce))
    }

    @Test
    fun `an authenticated challenge produces the finish proof and session key`() {
        val response = protocol.read(ByteArrayInputStream(hex(CHALLENGE)))
        val session = protocol.acceptChallenge(clientNonce, response)

        assertContentEquals("ponmlkjihgfedcba".toByteArray(), session.remoteNonce)
        assertContentEquals(hex("9f550d6da95513a14ca417a3bd35cc3e3de60e34cd6be064381d8ef89359e198"), session.finishPayload)
        assertContentEquals(hex("9ffa085e8b5849b3ab12b3096d8b0e9a"), session.key)
    }

    @Test
    fun `a challenge for a different client nonce is rejected`() {
        val response = protocol.read(ByteArrayInputStream(hex(CHALLENGE)))

        assertFailsWith<IOException> {
            protocol.acceptChallenge("different nonce!".toByteArray(), response)
        }
    }

    @Test
    fun `a normal query matches the protocol reference packet`() {
        assertContentEquals(hex(QUERY), protocol.encode(8, 16, "{}".toByteArray()))
    }

    @Test
    fun `control payload includes the encrypted version header`() {
        val payload = """{"protocol":5,"t":123,"data":{"dps":{"1":true}}}""".toByteArray()

        assertContentEquals(hex(CONTROL), protocol.encode(11, 13, payload))
    }

    @Test
    fun `query replies preserve sequence command return code and datapoints`() {
        val frame = protocol.read(ByteArrayInputStream(hex(QUERY_REPLY)))

        assertEquals(8, frame.sequence)
        assertEquals(16, frame.command)
        assertEquals(0, frame.returnCode)
        assertEquals("""{"dps":{"1":true,"101":true}}""", frame.payload.toString(Charsets.UTF_8))
    }

    @Test
    fun `incremental reports discard the version header but preserve their json body`() {
        val frame = protocol.read(ByteArrayInputStream(hex(REPORT)))

        assertEquals(8, frame.command)
        assertEquals("""{"protocol":4,"t":1,"data":{"dps":{"108":207}}}""", frame.payload.toString(Charsets.UTF_8))
    }

    @Test
    fun `empty acknowledgements have no encrypted payload`() {
        val frame = protocol.read(ByteArrayInputStream(hex(ACK)))

        assertEquals(13, frame.command)
        assertEquals(0, frame.returnCode)
        assertContentEquals(byteArrayOf(), frame.payload)
    }

    @Test
    fun `nonzero source sequencing fields are removed from an incremental report`() {
        val frame = protocol.read(ByteArrayInputStream(hex(SOURCE_HEADER)))

        assertEquals("""{"dps":{"1":true}}""", frame.payload.toString(Charsets.UTF_8))
    }

    @Test
    fun `authenticated payloads with invalid padding or block length are rejected`() {
        listOf(BAD_PADDING, BAD_BLOCK).forEach { packet ->
            assertFailsWith<IOException> { protocol.read(ByteArrayInputStream(hex(packet))) }
        }
    }

    @Test
    fun `fragmented reads consume exactly one frame at a time`() {
        val stream = object : ByteArrayInputStream(hex(QUERY_REPLY) + hex(REPORT)) {
            override fun read(bytes: ByteArray, offset: Int, length: Int): Int = super.read(bytes, offset, minOf(length, 3))
        }

        assertEquals(16, protocol.read(stream).command)
        assertEquals(8, protocol.read(stream).command)
        assertEquals(-1, stream.read())
    }

    @Test
    fun `modified ciphertext is rejected before values can be consumed`() {
        val packet = hex(QUERY_REPLY)
        packet[23] = (packet[23].toInt() xor 1).toByte()

        assertFailsWith<IOException> { protocol.read(ByteArrayInputStream(packet)) }
    }

    @Test
    fun `wrong integrity keys cannot authenticate a frame`() {
        assertFailsWith<IOException> {
            protocol.read(ByteArrayInputStream(hex(QUERY_REPLY)), "fedcba9876543210".toByteArray())
        }
    }

    @Test
    fun `invalid frame markers and lengths are rejected`() {
        val packets = listOf(
            "00006699000000080000001000000048",
            "000055aa0000000800000010ffffffff",
            "000055aa000000080000001000010001",
            "000055aa000000080000001000000001",
        )

        packets.forEach { packet ->
            assertFailsWith<IOException> { protocol.read(ByteArrayInputStream(hex(packet))) }
        }
        val suffix = hex(QUERY_REPLY)
        suffix[suffix.lastIndex] = 0
        assertFailsWith<IOException> { protocol.read(ByteArrayInputStream(suffix)) }
    }

    @Test
    fun `truncated packets fail instead of returning partial datapoints`() {
        assertFailsWith<EOFException> {
            protocol.read(ByteArrayInputStream(hex(QUERY_REPLY).dropLast(1).toByteArray()))
        }
    }

    @Test
    fun `the pre-shared key must be exactly sixteen bytes`() {
        assertFailsWith<IllegalArgumentException> { TuyaLanProtocol(byteArrayOf(1)) }
    }

    private fun hex(value: String): ByteArray = value.chunked(2).map { it.toInt(16).toByte() }.toByteArray()

    private companion object {
        const val START = "000055aa00000007000000030000004485627df0451e7740eb260b1df1f4fc64377222e061a924c591cd9c27ea163ed480a50326409ab93cec5bd8c76ebcb9767d3e5ddbdf43d43220d607c42953ea9d0000aa55"
        const val CHALLENGE = "000055aa00000007000000040000006800000000a118ba3a27c06fe8e7460a59605b782b69ed70381a5fdc1f0208a319d1a63489d242a0b9a9af284bd9e93b2a15e0ec26377222e061a924c591cd9c27ea163ed49b528d35d53b33ce87f9e359a91f521ff6c7445c2b0e23b3c8d5a004afb118c80000aa55"
        const val QUERY = "000055aa000000080000001000000034cb70ddc25a2a2045b4c13084418a9abb2ec45200b0bda05c856d1b27187e29042a44eb1c30ebf418f8ae7629af9e677e0000aa55"
        const val QUERY_REPLY = "000055aa00000008000000100000004800000000c27ee03f8be481e63320de7dc6eb429682b77332b1118d5c8d1db7cf106a7178e81467854c1be526e15354dfe0e03d130bb388ab1e2b637224e72a76f8026a870000aa55"
        const val REPORT = "000055aa000000090000000800000068000000004490b05d74be9368c24a038cbaeded8e98f10abffdce4e88bec061ae703238c2f75d083e1a57e0625aa130b2793cec5dd9cf2c1aa3355abf4abfca6781f8d7a31b5c52f16641632125e5b2a85e74a8b8e38e7d6440dedf072f4573782f41b4dd0000aa55"
        const val ACK = "000055aa0000000a0000000d000000280000000068162fc3ad34bd73ef6adbdda4cb337f26da30dc1d3612419f17f53e953cfe060000aa55"
        const val CONTROL = "000055aa0000000b0000000d000000644490b05d74be9368c24a038cbaeded8e89ea503e4be494dfe0c010bc6c463c7512a355c35e2563bbd0ea189081089724cac1b9db93b0d3a2f7f10e4a9e9874f45b16d027acb1b020a5a416fd5ff2d9e8005091f11218c3636467b1884e9144d10000aa55"
        const val BAD_PADDING = "000055aa00000008000000100000004800000000c27ee03f8be481e63320de7dc6eb429664215f365b0dad6b2ac8fab15b1d40bc76a2f2dbc79bffe0ca6d54d000b1dca19942bee47204299f8e44b01cf407be930000aa55"
        const val BAD_BLOCK = "000055aa00000008000000100000002b00000000616263a248b5f9d9438672ce01096c3e8a5fdd3c2d36333f5cc5e3a7efbc0212fffdd70000aa55"
        const val SOURCE_HEADER = "000055aa00000008000000080000005800000000d3e02e02abacb4c3e66f031d664a375441fb8ef70a70a27b93a7e74ffe75426303000aeb4ff51d29188f82e4a162a1f6040e5ddc3c39202a8c388ec6e7e091bbbbf3fb94372beec2de465e9185a7e77e0000aa55"
    }
}
